<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { createPermission, listPermissions, profilesForPermission, setPermissionState, updatePermission, type Permission, type PermissionPayload } from "@/services/administracion";

const known = ["BENEFICIARIOS_CONSULTAR", "BENEFICIARIOS_REGISTRAR", "BENEFICIARIOS_VALIDAR", "BENEFICIARIOS_MODIFICAR", "TARJETAS_CONSULTAR", "TARJETAS_ACTIVAR", "TARJETAS_ASIGNAR", "ACCESOS_CONSULTAR", "ACCESOS_HISTORIAL", "USUARIOS_ADMINISTRAR", "PERFILES_ADMINISTRAR", "PERMISOS_ADMINISTRAR", "CONFIGURACION_ADMINISTRAR", "AUDITORIA_CONSULTAR"];
const items = ref<Permission[]>([]); const search = ref(""); const modulo = ref(""); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const editing = ref<Permission | null>(null); const showForm = ref(false); const target = ref<Permission | null>(null);
const form = ref({ codigoPermiso: "", nombrePermiso: "", descripcionPermiso: "", moduloPermiso: "" }); const associated = ref<Array<{ idPerfil: number; codigoPerfil: string; nombrePerfil: string; estadoPerfil: boolean }>>([]); const showAssociated = ref(false); const associateError = ref(""); const associatedLoading = ref(false);
const modules = computed(() => [...new Set(items.value.map(item => item.moduloPermiso))].sort()); const availableCodes = computed(() => known.filter(code => !items.value.some(item => item.codigoPermiso === code)));
const message = (e: unknown) => e instanceof Error ? e.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listPermissions({ page: page.value, pageSize: 10, search: search.value, modulo: modulo.value }); items.value = result.items; pagination.value = result.pagination; } catch (e) { error.value = message(e); } finally { loading.value = false; } }
function edit(item: Permission | null) { editing.value = item; form.value = { codigoPermiso: item?.codigoPermiso ?? availableCodes.value[0] ?? "", nombrePermiso: item?.nombrePermiso ?? "", descripcionPermiso: item?.descripcionPermiso ?? "", moduloPermiso: item?.moduloPermiso ?? "" }; showForm.value = true; }
async function save() { saving.value = true; error.value = ""; try { const payload: PermissionPayload = { ...form.value, descripcionPermiso: form.value.descripcionPermiso || null }; if (editing.value) await updatePermission(editing.value.idPermiso, payload); else await createPermission(payload); showForm.value = false; success.value = "Permiso guardado correctamente."; await load(); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
async function showProfiles(item: Permission) { target.value = item; showAssociated.value = true; associatedLoading.value = true; associateError.value = ""; try { associated.value = await profilesForPermission(item.idPermiso); } catch (e) { associateError.value = message(e); } finally { associatedLoading.value = false; } }
async function toggle() { const item = target.value; target.value = null; if (!item) return; try { await setPermissionState(item.idPermiso, !item.estadoPermiso); success.value = `Permiso ${item.estadoPermiso ? "desactivado" : "activado"}.`; await load(); } catch (e) { error.value = message(e); } }
watch([search, modulo], () => { page.value = 1; void load(); }); onMounted(() => void load());
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración' }, { label: 'Permisos' }]" />
  <PageHeader eyebrow="Administración" title="Permisos" description="Catálogo limitado a operaciones que el backend autoriza explícitamente." :action-label="availableCodes.length ? 'Registrar operación' : undefined" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success" role="status">{{ success }}</div><div v-if="error" class="bo-state bo-state-error" role="alert">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar código o descripción..." aria-label="Buscar permisos" /><select v-model="modulo" aria-label="Filtrar módulo"><option value="">Todos los módulos</option><option v-for="item in modules" :key="item" :value="item">{{ item }}</option></select><button class="bo-btn bo-btn-primary">Buscar</button></form>
    <div v-if="loading" class="bo-state">Cargando permisos...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay permisos para mostrar.</strong></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Permiso</th><th>Módulo</th><th>Perfiles asignados</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idPermiso"><td><strong>{{ item.nombrePermiso }}</strong><br /><small>{{ item.codigoPermiso }} · {{ item.descripcionPermiso || 'Sin descripción' }}</small></td><td>{{ item.moduloPermiso }}</td><td>{{ item.perfiles }}</td><td><StatusBadge :active="item.estadoPermiso" /></td><td><div class="bo-actions"><button class="bo-action" @click="showProfiles(item)">Perfiles</button><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoPermiso }" @click="target = item">{{ item.estadoPermiso ? 'Desactivar' : 'Activar' }}</button></div></td></tr></tbody></table></div>
    <footer class="bo-pagination"><span>{{ pagination.total }} permisos · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1 || loading" @click="page--; load()">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages || loading" @click="page++; load()">Siguiente</button></div></footer>
  </section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Catálogo de permisos operativos</span><h2>{{ editing ? 'Editar permiso' : 'Registrar operación existente' }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><p class="bo-state">Solo se aceptan códigos asociados a rutas y métodos existentes del backend; crear un registro no asigna el permiso a ningún perfil.</p><form class="bo-form" @submit.prevent="save"><label>Código operativo *<select v-model="form.codigoPermiso" :disabled="Boolean(editing)" required><option v-for="code in editing ? [editing.codigoPermiso] : availableCodes" :key="code" :value="code">{{ code }}</option></select></label><label>Nombre *<input v-model="form.nombrePermiso" maxlength="150" required /></label><label>Módulo *<input v-model="form.moduloPermiso" maxlength="50" required /></label><label>Descripción<textarea v-model="form.descripcionPermiso" maxlength="500" rows="3" /></label><footer class="bo-form-actions"><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving || (!editing && !availableCodes.length)">{{ saving ? 'Guardando...' : 'Guardar' }}</button></footer></form></section></div>
  <div v-if="showAssociated" class="bo-modal-backdrop" @click.self="showAssociated = false; target = null"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ target?.codigoPermiso }}</span><h2>Perfiles asociados</h2></div><button class="bo-close" type="button" @click="showAssociated = false; target = null">×</button></header><div v-if="associatedLoading" class="bo-state">Cargando perfiles...</div><p v-else-if="associateError" class="bo-form-error">{{ associateError }}</p><ul v-else-if="associated.length" class="bo-related-list"><li v-for="item in associated" :key="item.idPerfil"><strong>{{ item.nombrePerfil }}</strong><span>{{ item.codigoPerfil }} · {{ item.estadoPerfil ? 'Activo' : 'Inactivo' }}</span></li></ul><div v-else class="bo-state">El permiso no está asignado a perfiles.</div></section></div>
  <ConfirmDialog :open="Boolean(target) && !showAssociated" title="Cambiar estado del permiso" :message="target ? `¿Desea ${target.estadoPermiso ? 'desactivar' : 'activar'} el permiso ${target.codigoPermiso}?` : ''" :confirm-label="target?.estadoPermiso ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="target = null" />
</template>
